update known_safe_harbors set evidence_summary = 'FOUNDING PAPER of human H11: "we identified a novel human locus, H11, located in a safe, transcriptionally active intergenic region of chromosome 22" (confirms band 22q12.2 already on record via review). DICE system (dual cassette exchange via phiC31+Bxb1 integrases) with 100% specificity. Tested with mCherry and neural transcription factors (LMX1a, FOXA2, OTX2) in ESC/iPSC lines, including iPSC from a Parkinson''s patient and a healthy sibling control -- directly relevant to neuronal/dopaminergic differentiation.', stability = '100% specificity for DICE system; validated across neural transcription factor payloads' where source_pmid = '24304893' and evidence_summary = 'PAPER FUNDADOR do H11 humano: "identificámos um novo locus humano, H11, situado numa região intergénica segura e transcricionalmente ativa do cromossoma 22" (confirma banda 22q12.2 já registada via review). Sistema DICE (dupla troca de cassete por integrases phiC31+Bxb1) com especificidade de 100%. Testado com mCherry e fatores de transcrição neurais (LMX1a, FOXA2, OTX2) em linhas ESC/iPSC, incluindo iPSC de doente de Parkinson e irmão saudável de controlo -- diretamente relevante a diferenciação neuronal/dopaminérgica.';
update public_safe_harbors_staging set evidence_summary = 'FOUNDING PAPER of human H11: "we identified a novel human locus, H11, located in a safe, transcriptionally active intergenic region of chromosome 22" (confirms band 22q12.2 already on record via review). DICE system (dual cassette exchange via phiC31+Bxb1 integrases) with 100% specificity. Tested with mCherry and neural transcription factors (LMX1a, FOXA2, OTX2) in ESC/iPSC lines, including iPSC from a Parkinson''s patient and a healthy sibling control -- directly relevant to neuronal/dopaminergic differentiation.', stability = '100% specificity for DICE system; validated across neural transcription factor payloads' where source_pmid = '24304893' and evidence_summary = 'PAPER FUNDADOR do H11 humano: "identificámos um novo locus humano, H11, situado numa região intergénica segura e transcricionalmente ativa do cromossoma 22" (confirma banda 22q12.2 já registada via review). Sistema DICE (dupla troca de cassete por integrases phiC31+Bxb1) com especificidade de 100%. Testado com mCherry e fatores de transcrição neurais (LMX1a, FOXA2, OTX2) em linhas ESC/iPSC, incluindo iPSC de doente de Parkinson e irmão saudável de controlo -- diretamente relevante a diferenciação neuronal/dopaminérgica.';

update known_safe_harbors set evidence_summary = 'Cas9-N57 fusion nuclease (Sleeping Beauty transposon DNA-binding domain fused to Cas9) used to insert an anti-CD19 CAR cassette at AAVS1 in human T cells -- unidirectional, specific insertion, fragments up to 12kb successfully integrated.', stability = 'Successful integration of fragments up to 12kb (duration not further quantified)' where source_pmid = '32986839' and evidence_summary = 'Nuclease de fusão Cas9-N57 (domínio de ligação a DNA do transposão Sleeping Beauty fundido a Cas9) usada para inserir cassete CAR anti-CD19 em AAVS1 em células T humanas -- inserção unidirecional e específica, fragmentos até 12kb integrados com sucesso.';
