update known_safe_harbors set evidence_summary = 'Same Cas9-N57 system used to insert oncogenic KrasG12D at ROSA26 (plus disruption of Trp53/Pten) to induce intrahepatic cholangiocarcinoma in mice -- not a locus failure, it confirms that ROSA26 expresses an inserted oncogene reliably and on command, used deliberately as a cancer model. Relevant as proof of reliable, controllable expression, even if in a different application context.', stability = 'Reliable, controllable expression (used deliberately as a cancer model)' where source_pmid = '32986839' and evidence_summary = 'Mesmo sistema Cas9-N57 usado para inserir KrasG12D oncogénico em ROSA26 (mais disrupção de Trp53/Pten) para induzir colangiocarcinoma intra-hepático em ratinhos -- não é falha do locus, é confirmação de que ROSA26 expressa de forma fiável e sob comando um oncogene inserido, usado deliberadamente como modelo de cancro. Relevante como prova de expressão fiável e controlável, ainda que noutro contexto de aplicação.';
update public_safe_harbors_staging set evidence_summary = 'Same Cas9-N57 system used to insert oncogenic KrasG12D at ROSA26 (plus disruption of Trp53/Pten) to induce intrahepatic cholangiocarcinoma in mice -- not a locus failure, it confirms that ROSA26 expresses an inserted oncogene reliably and on command, used deliberately as a cancer model. Relevant as proof of reliable, controllable expression, even if in a different application context.', stability = 'Reliable, controllable expression (used deliberately as a cancer model)' where source_pmid = '32986839' and evidence_summary = 'Mesmo sistema Cas9-N57 usado para inserir KrasG12D oncogénico em ROSA26 (mais disrupção de Trp53/Pten) para induzir colangiocarcinoma intra-hepático em ratinhos -- não é falha do locus, é confirmação de que ROSA26 expressa de forma fiável e sob comando um oncogene inserido, usado deliberadamente como modelo de cancro. Relevante como prova de expressão fiável e controlável, ainda que noutro contexto de aplicação.';

update known_safe_harbors set evidence_summary = 'Anti-HIV CAR (scFv from bNAb 10-1074) integrated at CCR5 in human T cells via CRISPR/Cas9. Specific lysis of HIV-infected cells in vitro. In a humanized PBMC mouse model, the CAR-T cells expanded and transiently limited HIV infection in vivo.', stability = 'Transient limitation of infection in vivo (duration not further quantified)' where source_pmid = '36680242' and evidence_summary = 'CAR anti-HIV (scFv do bNAb 10-1074) integrado em CCR5 em células T humanas via CRISPR/Cas9. Lise específica de células infetadas com HIV in vitro. Em modelo de ratinho humanizado com PBMCs, as células CAR-T expandiram e limitaram transitoriamente a infeção por HIV in vivo.';
update public_safe_harbors_staging set evidence_summary = 'Anti-HIV CAR (scFv from bNAb 10-1074) integrated at CCR5 in human T cells via CRISPR/Cas9. Specific lysis of HIV-infected cells in vitro. In a humanized PBMC mouse model, the CAR-T cells expanded and transiently limited HIV infection in vivo.', stability = 'Transient limitation of infection in vivo (duration not further quantified)' where source_pmid = '36680242' and evidence_summary = 'CAR anti-HIV (scFv do bNAb 10-1074) integrado em CCR5 em células T humanas via CRISPR/Cas9. Lise específica de células infetadas com HIV in vitro. Em modelo de ratinho humanizado com PBMCs, as células CAR-T expandiram e limitaram transitoriamente a infeção por HIV in vivo.';

update known_safe_harbors set evidence_summary = 'Not transgene insertion, this is CCR5 disruption by CRISPR/Cas9 in iPSCs (12.5% editing with a single gRNA, rising to 27% with dual gRNA). iPSC lines homozygous for mutated CCR5 retained pluripotency characteristics and differentiated efficiently into hematopoietic cells, including macrophages. Edited macrophages were specifically resistant to CCR5-tropic virus, but not CXCR4-tropic virus -- confirms CCR5 loss is functionally well tolerated.', stability = 'Well tolerated functionally; pluripotency retained' where source_pmid = '26670276' and evidence_summary = 'Não é inserção de transgene, é disrupção de CCR5 por CRISPR/Cas9 em iPSCs (12.5% edição com gRNA único, subindo a 27% com gRNA duplo). Linhas iPSC homozigóticas para CCR5 mutado mantiveram características de pluripotência e diferenciaram eficientemente em células hematopoiéticas, incluindo macrófagos. Macrófagos editados resistentes especificamente a vírus CCR5-trópico, mas não a vírus CXCR4-trópico -- confirma que a perda de CCR5 é bem tolerada funcionalmente.';
update public_safe_harbors_staging set evidence_summary = 'Not transgene insertion, this is CCR5 disruption by CRISPR/Cas9 in iPSCs (12.5% editing with a single gRNA, rising to 27% with dual gRNA). iPSC lines homozygous for mutated CCR5 retained pluripotency characteristics and differentiated efficiently into hematopoietic cells, including macrophages. Edited macrophages were specifically resistant to CCR5-tropic virus, but not CXCR4-tropic virus -- confirms CCR5 loss is functionally well tolerated.', stability = 'Well tolerated functionally; pluripotency retained' where source_pmid = '26670276' and evidence_summary = 'Não é inserção de transgene, é disrupção de CCR5 por CRISPR/Cas9 em iPSCs (12.5% edição com gRNA único, subindo a 27% com gRNA duplo). Linhas iPSC homozigóticas para CCR5 mutado mantiveram características de pluripotência e diferenciaram eficientemente em células hematopoiéticas, incluindo macrófagos. Macrófagos editados resistentes especificamente a vírus CCR5-trópico, mas não a vírus CXCR4-trópico -- confirma que a perda de CCR5 é bem tolerada funcionalmente.';

-- ===== batch 11 =====
update known_safe_harbors set evidence_summary = 'FOUNDING PAPER for using TRAC in CAR-T (Eyquem et al., highly cited). Anti-CD19 CAR directed to the TRAC locus (not random integration): uniform CAR expression in human peripheral blood T cells, increased potency vs. conventional CAR-T, with far superior performance in a mouse model of acute lymphoblastic leukemia. Avoids tonic CAR signaling, allows effective internalization/re-expression after repeated antigen exposure, delays effector T-cell differentiation and exhaustion.', stability = 'Delays exhaustion; superior in vivo performance vs. conventional CAR-T' where source_pmid = '28225754' and evidence_summary = 'PAPER FUNDADOR do uso de TRAC para CAR-T (Eyquem et al., muito citado). CAR anti-CD19 direcionado ao locus TRAC (não integração aleatória): expressão uniforme do CAR em células T de sangue periférico humano, potência aumentada face a CAR-T convencional, com desempenho muito superior num modelo de ratinho de leucemia linfoblástica aguda. Evita sinalização tónica do CAR, permite internalização/re-expressão eficaz após exposição repetida ao antigénio, atrasa diferenciação e exaustão das células T efetoras.';
update public_safe_harbors_staging set evidence_summary = 'FOUNDING PAPER for using TRAC in CAR-T (Eyquem et al., highly cited). Anti-CD19 CAR directed to the TRAC locus (not random integration): uniform CAR expression in human peripheral blood T cells, increased potency vs. conventional CAR-T, with far superior performance in a mouse model of acute lymphoblastic leukemia. Avoids tonic CAR signaling, allows effective internalization/re-expression after repeated antigen exposure, delays effector T-cell differentiation and exhaustion.', stability = 'Delays exhaustion; superior in vivo performance vs. conventional CAR-T' where source_pmid = '28225754' and evidence_summary = 'PAPER FUNDADOR do uso de TRAC para CAR-T (Eyquem et al., muito citado). CAR anti-CD19 direcionado ao locus TRAC (não integração aleatória): expressão uniforme do CAR em células T de sangue periférico humano, potência aumentada face a CAR-T convencional, com desempenho muito superior num modelo de ratinho de leucemia linfoblástica aguda. Evita sinalização tónica do CAR, permite internalização/re-expressão eficaz após exposição repetida ao antigénio, atrasa diferenciação e exaustão das células T efetoras.';

update known_safe_harbors set evidence_summary = 'Anti-CD19 CAR inserted directly into the native TRAC locus via homing endonuclease + AAV donor template. Resulting cells do not express the endogenous TCR, show potent effector functions in vitro, and eliminate CD19+ tumors in a mouse model in vivo -- specifically designed for allogeneic production (avoids GvHD by eliminating the endogenous TCR through the insertion itself).', stability = 'Eliminates tumors in vivo; designed for allogeneic durability (GvHD avoidance)' where source_pmid = '28237835' and evidence_summary = 'CAR anti-CD19 inserido diretamente no locus TRAC nativo via endonuclease de homing + molde dador AAV. Células resultantes não expressam o TCR endógeno, mostram funções efetoras potentes in vitro, e eliminam tumores CD19+ num modelo de ratinho in vivo -- desenhado especificamente para produção alogénica (evita GvHD ao eliminar o TCR endógeno pela própria inserção).';
update public_safe_harbors_staging set evidence_summary = 'Anti-CD19 CAR inserted directly into the native TRAC locus via homing endonuclease + AAV donor template. Resulting cells do not express the endogenous TCR, show potent effector functions in vitro, and eliminate CD19+ tumors in a mouse model in vivo -- specifically designed for allogeneic production (avoids GvHD by eliminating the endogenous TCR through the insertion itself).', stability = 'Eliminates tumors in vivo; designed for allogeneic durability (GvHD avoidance)' where source_pmid = '28237835' and evidence_summary = 'CAR anti-CD19 inserido diretamente no locus TRAC nativo via endonuclease de homing + molde dador AAV. Células resultantes não expressam o TCR endógeno, mostram funções efetoras potentes in vitro, e eliminam tumores CD19+ num modelo de ratinho in vivo -- desenhado especificamente para produção alogénica (evita GvHD ao eliminar o TCR endógeno pela própria inserção).';

update known_safe_harbors set evidence_summary = 'Virus-free editing method (CRISPR-Cas + double-stranded DNA template) optimized for CAR insertion at TRAC, combining DNA-sensor inhibition with HDR potentiation -- CAR knock-in rates at TRAC above 50% of cells. Resulting CAR-T cells showed antigen-specific cytotoxicity and cytokine production in vitro, and slowed leukemia progression in a mouse xenograft model. Amplicon sequencing revealed no significant indel formation at potential off-target sites.', stability = 'Knock-in rate >50%; slowed leukemia progression in vivo' where source_pmid = '35573047' and evidence_summary = 'Método de edição sem vírus (CRISPR-Cas + DNA molde de cadeia dupla) otimizado para inserção de CAR em TRAC, combinando inibição de sensores de DNA com potenciação de HDR -- taxas de knock-in de CAR em TRAC superiores a 50% das células. Células CAR-T resultantes mostraram citotoxicidade específica de antigénio e produção de citocinas in vitro, e abrandaram progressão de leucemia num modelo de xenoenxerto em ratinho. Sequenciação de amplicões não revelou formação significativa de indels em sítios off-target potenciais.';
update public_safe_harbors_staging set evidence_summary = 'Virus-free editing method (CRISPR-Cas + double-stranded DNA template) optimized for CAR insertion at TRAC, combining DNA-sensor inhibition with HDR potentiation -- CAR knock-in rates at TRAC above 50% of cells. Resulting CAR-T cells showed antigen-specific cytotoxicity and cytokine production in vitro, and slowed leukemia progression in a mouse xenograft model. Amplicon sequencing revealed no significant indel formation at potential off-target sites.', stability = 'Knock-in rate >50%; slowed leukemia progression in vivo' where source_pmid = '35573047' and evidence_summary = 'Método de edição sem vírus (CRISPR-Cas + DNA molde de cadeia dupla) otimizado para inserção de CAR em TRAC, combinando inibição de sensores de DNA com potenciação de HDR -- taxas de knock-in de CAR em TRAC superiores a 50% das células. Células CAR-T resultantes mostraram citotoxicidade específica de antigénio e produção de citocinas in vitro, e abrandaram progressão de leucemia num modelo de xenoenxerto em ratinho. Sequenciação de amplicões não revelou formação significativa de indels em sítios off-target potenciais.';

update known_safe_harbors set evidence_summary = 'CELiD (AAV-dependent) vector for CAR integration at AAVS1 in Jurkat cells: of 71 stably transfected clones tested, 30 contained the CAR gene within the AAVS1 site -- site-specific integration efficiency of 42.2%, quantified by nested PCR, sequencing, and Southern blot.', stability = 'Integration efficiency 42.2% (duration not further quantified)' where source_pmid = '27271519' and evidence_summary = 'Vetor CELiD (AAV-dependente) para integração de CAR em AAVS1 em células Jurkat: de 71 clones estavelmente transfetados testados, 30 continham o gene CAR dentro do sítio AAVS1 -- eficiência de integração sítio-específica de 42.2%, quantificada por PCR aninhada, sequenciação e Southern blot.';
update public_safe_harbors_staging set evidence_summary = 'CELiD (AAV-dependent) vector for CAR integration at AAVS1 in Jurkat cells: of 71 stably transfected clones tested, 30 contained the CAR gene within the AAVS1 site -- site-specific integration efficiency of 42.2%, quantified by nested PCR, sequencing, and Southern blot.', stability = 'Integration efficiency 42.2% (duration not further quantified)' where source_pmid = '27271519' and evidence_summary = 'Vetor CELiD (AAV-dependente) para integração de CAR em AAVS1 em células Jurkat: de 71 clones estavelmente transfetados testados, 30 continham o gene CAR dentro do sítio AAVS1 -- eficiência de integração sítio-específica de 42.2%, quantificada por PCR aninhada, sequenciação e Southern blot.';

update known_safe_harbors set evidence_summary = 'Founding mechanistic paper (2000), explains WHY AAVS1 works: the Rep binding site (RBS) within AAVS1 is located near a DNase-I-hypersensitive "open" chromatin region, with enhancer-like transcriptional properties -- a "transcriptionally competent environment" that explains the locus''s accessibility to integration and AAV Rep proteins. Open conformation also confirmed in transgenic mice carrying the AAVS1 fragment.', stability = 'Mechanistic explanation for chromatin accessibility (not a duration measurement)' where source_pmid = '10906224' and evidence_summary = 'Paper mecanístico fundador (2000), explica PORQUÊ o AAVS1 funciona: o sítio de ligação Rep (RBS) dentro de AAVS1 está localizado perto de uma região de cromatina "aberta" hipersensível a DNase I, com propriedades semelhantes a um enhancer transcricional -- um "ambiente transcricionalmente competente" que explica a acessibilidade do locus a integração e a proteínas Rep do AAV. Conformação aberta confirmada também em ratos transgénicos portadores do fragmento AAVS1.';
update public_safe_harbors_staging set evidence_summary = 'Founding mechanistic paper (2000), explains WHY AAVS1 works: the Rep binding site (RBS) within AAVS1 is located near a DNase-I-hypersensitive "open" chromatin region, with enhancer-like transcriptional properties -- a "transcriptionally competent environment" that explains the locus''s accessibility to integration and AAV Rep proteins. Open conformation also confirmed in transgenic mice carrying the AAVS1 fragment.', stability = 'Mechanistic explanation for chromatin accessibility (not a duration measurement)' where source_pmid = '10906224' and evidence_summary = 'Paper mecanístico fundador (2000), explica PORQUÊ o AAVS1 funciona: o sítio de ligação Rep (RBS) dentro de AAVS1 está localizado perto de uma região de cromatina "aberta" hipersensível a DNase I, com propriedades semelhantes a um enhancer transcricional -- um "ambiente transcricionalmente competente" que explica a acessibilidade do locus a integração e a proteínas Rep do AAV. Conformação aberta confirmada também em ratos transgénicos portadores do fragmento AAVS1.';

update known_safe_harbors set evidence_summary = 'Important biological caveat (not transgene expression data, this is endogenous locus biology): CLYBL encodes a real enzyme with its own function -- it repairs malyl-CoA, a citric-acid-cycle byproduct, preventing inhibition of methylmalonyl-CoA mutase and vitamin B12 depletion. CLYBL knockout has a real, measurable metabolic consequence, though apparently tolerable in the safe-harbor studies already on record. Worth not treating CLYBL as "neutral" without qualification.', stability = 'Real endogenous metabolic effect, independent of transgene silencing/duration' where source_pmid = '40108300' and evidence_summary = 'Ressalva biológica a ter em conta (não é dado de expressão de transgene, é biologia endógena do locus): CLYBL codifica uma enzima real com função própria -- repara malil-CoA, um subproduto do ciclo do ácido cítrico, prevenindo inibição da metilmalonil-CoA mutase e depleção de vitamina B12. Knockout de CLYBL tem consequência metabólica real, mensurável, ainda que aparentemente tolerável nos estudos de safe harbor já registados. Vale a pena não tratar CLYBL como "neutro" sem qualificação.';
update public_safe_harbors_staging set evidence_summary = 'Important biological caveat (not transgene expression data, this is endogenous locus biology): CLYBL encodes a real enzyme with its own function -- it repairs malyl-CoA, a citric-acid-cycle byproduct, preventing inhibition of methylmalonyl-CoA mutase and vitamin B12 depletion. CLYBL knockout has a real, measurable metabolic consequence, though apparently tolerable in the safe-harbor studies already on record. Worth not treating CLYBL as "neutral" without qualification.', stability = 'Real endogenous metabolic effect, independent of transgene silencing/duration' where source_pmid = '40108300' and evidence_summary = 'Ressalva biológica a ter em conta (não é dado de expressão de transgene, é biologia endógena do locus): CLYBL codifica uma enzima real com função própria -- repara malil-CoA, um subproduto do ciclo do ácido cítrico, prevenindo inibição da metilmalonil-CoA mutase e depleção de vitamina B12. Knockout de CLYBL tem consequência metabólica real, mensurável, ainda que aparentemente tolerável nos estudos de safe harbor já registados. Vale a pena não tratar CLYBL como "neutro" sem qualificação.';

