update known_safe_harbors set evidence_summary = 'Cas9-CLIPT system (circular plasmid linearized in vitro by Cas9-RNP itself) for non-viral insertion at TRAC: up to 60% precise knock-in efficiency with NHEJ inhibition, even with large transgenes (2-6kb). Resulting anti-GD2 CAR-T cells (neuroblastoma) were potent, with a phenotype enriched in stem-cell memory.', stability = 'Knock-in up to 60%; potent CAR-T with stem-cell-memory phenotype' where source_pmid = '40123742' and evidence_summary = 'Sistema Cas9-CLIPT (plasmídeo circular linearizado in vitro pelo próprio Cas9-RNP) para inserção não-viral em TRAC: até 60% de eficiência de knock-in preciso com inibição de NHEJ, mesmo com transgenes grandes (2-6kb). Células CAR-T anti-GD2 (neuroblastoma) resultantes potentes, com fenótipo enriquecido em memória de células estaminais.';
update public_safe_harbors_staging set evidence_summary = 'Cas9-CLIPT system (circular plasmid linearized in vitro by Cas9-RNP itself) for non-viral insertion at TRAC: up to 60% precise knock-in efficiency with NHEJ inhibition, even with large transgenes (2-6kb). Resulting anti-GD2 CAR-T cells (neuroblastoma) were potent, with a phenotype enriched in stem-cell memory.', stability = 'Knock-in up to 60%; potent CAR-T with stem-cell-memory phenotype' where source_pmid = '40123742' and evidence_summary = 'Sistema Cas9-CLIPT (plasmídeo circular linearizado in vitro pelo próprio Cas9-RNP) para inserção não-viral em TRAC: até 60% de eficiência de knock-in preciso com inibição de NHEJ, mesmo com transgenes grandes (2-6kb). Células CAR-T anti-GD2 (neuroblastoma) resultantes potentes, com fenótipo enriquecido em memória de células estaminais.';

update known_safe_harbors set locus_name = 'Random integration (vector-dependent -- lentiviral vs. gammaretroviral)', evidence_summary = 'Real longitudinal analysis in CAR-T patients: lentiviral integration concentrated in introns, with no major clonal proliferation after 1 year. Gammaretroviral integration concentrated in intergenic regions near transcription start sites -- divergent outcomes: one patient with no detectable CAR after 1 year, another with low-level oligoclonal persistence (future malignancy risk still unclear).', stability = 'Divergent long-term (1-year) persistence depending on vector type' where source_pmid = '39972592' and evidence_summary = 'Análise longitudinal real em doentes CAR-T: integração lentiviral concentrou-se em intrões, sem proliferação clonal major ao fim de 1 ano. Integração gamaretroviral concentrou-se em regiões intergénicas perto de locais de início de transcrição -- resultados divergentes: um doente sem CAR detetável ao fim de 1 ano, outro com persistência oligoclonal de baixo nível (risco de malignidade futura ainda por esclarecer).';
update public_safe_harbors_staging set locus_name = 'Random integration (vector-dependent -- lentiviral vs. gammaretroviral)', evidence_summary = 'Real longitudinal analysis in CAR-T patients: lentiviral integration concentrated in introns, with no major clonal proliferation after 1 year. Gammaretroviral integration concentrated in intergenic regions near transcription start sites -- divergent outcomes: one patient with no detectable CAR after 1 year, another with low-level oligoclonal persistence (future malignancy risk still unclear).', stability = 'Divergent long-term (1-year) persistence depending on vector type' where source_pmid = '39972592' and evidence_summary = 'Análise longitudinal real em doentes CAR-T: integração lentiviral concentrou-se em intrões, sem proliferação clonal major ao fim de 1 ano. Integração gamaretroviral concentrou-se em regiões intergénicas perto de locais de início de transcrição -- resultados divergentes: um doente sem CAR detetável ao fim de 1 ano, outro com persistência oligoclonal de baixo nível (risco de malignidade futura ainda por esclarecer).';

update known_safe_harbors set locus_name = 'General secondary malignancy risk post-CAR-T (context, not a specific locus)', evidence_summary = 'Real cohort of 449 patients treated with commercial CAR-T (CD19, BCMA): 3.6% developed a secondary malignancy at a median follow-up of 10.3 months; projected 5-year cumulative incidence of 15.2% (solid) and 2.3% (hematologic). Only 1 case of T-cell lymphoma effectively linked to the CAR (low transgene levels, pre-existing clone before infusion) -- authors'' conclusion: low risk of T-cell lymphoma attributable to CAR-T itself.', stability = 'Low long-term (5-year projected) malignancy risk attributable to the CAR itself' where source_pmid = '38266761' and evidence_summary = 'Coorte real de 449 doentes tratados com CAR-T comercial (CD19, BCMA): 3.6% desenvolveram malignidade secundária a um seguimento médio de 10.3 meses; incidência cumulativa projetada a 5 anos de 15.2% (sólida) e 2.3% (hematológica). Apenas 1 caso de linfoma de células T efetivamente ligado ao CAR (níveis baixos de transgene, clone pré-existente antes da infusão) -- conclusão dos autores: risco baixo de linfoma de células T atribuível ao CAR-T em si.';
update public_safe_harbors_staging set locus_name = 'General secondary malignancy risk post-CAR-T (context, not a specific locus)', evidence_summary = 'Real cohort of 449 patients treated with commercial CAR-T (CD19, BCMA): 3.6% developed a secondary malignancy at a median follow-up of 10.3 months; projected 5-year cumulative incidence of 15.2% (solid) and 2.3% (hematologic). Only 1 case of T-cell lymphoma effectively linked to the CAR (low transgene levels, pre-existing clone before infusion) -- authors'' conclusion: low risk of T-cell lymphoma attributable to CAR-T itself.', stability = 'Low long-term (5-year projected) malignancy risk attributable to the CAR itself' where source_pmid = '38266761' and evidence_summary = 'Coorte real de 449 doentes tratados com CAR-T comercial (CD19, BCMA): 3.6% desenvolveram malignidade secundária a um seguimento médio de 10.3 meses; incidência cumulativa projetada a 5 anos de 15.2% (sólida) e 2.3% (hematológica). Apenas 1 caso de linfoma de células T efetivamente ligado ao CAR (níveis baixos de transgene, clone pré-existente antes da infusão) -- conclusão dos autores: risco baixo de linfoma de células T atribuível ao CAR-T em si.';

update known_safe_harbors set locus_name = 'Random integration (piggyBac)', evidence_summary = 'REAL CLINICAL CASE, phase 1 trial: 2 patients developed lymphoma derived from CAR-modified T cells using the piggyBac transposon system (untargeted integration). Analysis of the first lymphoma: elevated transgene copy number, BUT no insertion in typical oncogenes -- the malignancy correlated more with copy number and unrelated structural genomic alterations than with the insertion site itself. The transgene promoter activated transcription of surrounding regions despite insulator sequences. One patient died.', stability = 'Untargeted random integration -- linked to lymphoma in a real clinical trial' where source_pmid = '33974080' and evidence_summary = 'CASO CLÍNICO REAL, ensaio de fase 1: 2 doentes desenvolveram linfoma derivado de células T CAR-modificadas com sistema de transposão piggyBac (integração não-direcionada). Análise do primeiro linfoma: número de cópias do transgene elevado, MAS sem inserção em oncogenes típicos -- a malignidade correlacionou-se mais com o número de cópias e alterações genómicas estruturais não relacionadas com o sítio de inserção do que com o próprio sítio. Promotor do transgene ativou transcrição das regiões circundantes apesar de sequências isoladoras (insulator). Um dos doentes morreu.';
update public_safe_harbors_staging set locus_name = 'Random integration (piggyBac)', evidence_summary = 'REAL CLINICAL CASE, phase 1 trial: 2 patients developed lymphoma derived from CAR-modified T cells using the piggyBac transposon system (untargeted integration). Analysis of the first lymphoma: elevated transgene copy number, BUT no insertion in typical oncogenes -- the malignancy correlated more with copy number and unrelated structural genomic alterations than with the insertion site itself. The transgene promoter activated transcription of surrounding regions despite insulator sequences. One patient died.', stability = 'Untargeted random integration -- linked to lymphoma in a real clinical trial' where source_pmid = '33974080' and evidence_summary = 'CASO CLÍNICO REAL, ensaio de fase 1: 2 doentes desenvolveram linfoma derivado de células T CAR-modificadas com sistema de transposão piggyBac (integração não-direcionada). Análise do primeiro linfoma: número de cópias do transgene elevado, MAS sem inserção em oncogenes típicos -- a malignidade correlacionou-se mais com o número de cópias e alterações genómicas estruturais não relacionadas com o sítio de inserção do que com o próprio sítio. Promotor do transgene ativou transcrição das regiões circundantes apesar de sequências isoladoras (insulator). Um dos doentes morreu.';

update known_safe_harbors set locus_name = 'Random integration (piggyBac)', evidence_summary = 'Related/companion report to the case above: 2 of 10 patients treated with piggyBac-modified CD19 CAR-T cells developed CAR-T-cell lymphoma. Low confidence as the full abstract could not be obtained -- only the title and exact count (2/10) are confirmed.', stability = 'Untargeted random integration -- linked to lymphoma in a real clinical trial (2/10 patients)' where source_pmid = '34010392' and evidence_summary = 'Relato relacionado/companheiro do caso acima: 2 de 10 doentes tratados com células CAR-T CD19 modificadas por piggyBac desenvolveram linfoma de células T CAR-T. Confiança baixa por não ter sido possível obter o abstract completo -- só o título e a contagem exata (2/10) estão confirmados.';
update public_safe_harbors_staging set locus_name = 'Random integration (piggyBac)', evidence_summary = 'Related/companion report to the case above: 2 of 10 patients treated with piggyBac-modified CD19 CAR-T cells developed CAR-T-cell lymphoma. Low confidence as the full abstract could not be obtained -- only the title and exact count (2/10) are confirmed.', stability = 'Untargeted random integration -- linked to lymphoma in a real clinical trial (2/10 patients)' where source_pmid = '34010392' and evidence_summary = 'Relato relacionado/companheiro do caso acima: 2 de 10 doentes tratados com células CAR-T CD19 modificadas por piggyBac desenvolveram linfoma de células T CAR-T. Confiança baixa por não ter sido possível obter o abstract completo -- só o título e a contagem exata (2/10) estão confirmados.';

update known_safe_harbors set locus_name = 'Random integration (lentivirus)', evidence_summary = 'Clonal expansion of CAR-T cells harboring lentiviral integration in the CBL gene following anti-CD22 CAR-T therapy -- a concerning proliferation signal linked to random integration at a specific gene. Low confidence as the full abstract could not be obtained, only the title.', stability = 'Concerning clonal proliferation signal linked to random integration site' where source_pmid = '31387880' and evidence_summary = 'Expansão clonal de células CAR-T com integração lentiviral no gene CBL após terapia CAR-T anti-CD22 -- sinal de proliferação preocupante ligado a integração aleatória num gene específico. Confiança baixa por não ter sido possível obter o abstract completo, só o título.';
update public_safe_harbors_staging set locus_name = 'Random integration (lentivirus)', evidence_summary = 'Clonal expansion of CAR-T cells harboring lentiviral integration in the CBL gene following anti-CD22 CAR-T therapy -- a concerning proliferation signal linked to random integration at a specific gene. Low confidence as the full abstract could not be obtained, only the title.', stability = 'Concerning clonal proliferation signal linked to random integration site' where source_pmid = '31387880' and evidence_summary = 'Expansão clonal de células CAR-T com integração lentiviral no gene CBL após terapia CAR-T anti-CD22 -- sinal de proliferação preocupante ligado a integração aleatória num gene específico. Confiança baixa por não ter sido possível obter o abstract completo, só o título.';

update known_safe_harbors set locus_name = 'Comparison of random-integration vectors (SB, piggyBac, MLV, lentivirus)', evidence_summary = 'Direct comparison of 4 systems in human CD4+ T cells: the Sleeping Beauty (SB) transposon showed the distribution closest to true randomness -- "highest theoretical probability of hitting a safe-harbor locus by chance" of the 4 systems. piggyBac and MLV retrovirus showed unexpectedly similar patterns to each other, enriched near transcription start sites, colocalizing with BRD4-associated sites -- a convergent "tethering" mechanism that preferentially directs them toward active genes (riskier).', stability = 'SB closest to true random distribution; piggyBac/MLV enriched near active genes (higher risk)' where source_pmid = '26755332' and evidence_summary = 'Comparação direta de 4 sistemas em células T CD4+ humanas: o transposão Sleeping Beauty (SB) mostrou a distribuição mais próxima do aleatório verdadeiro -- "maior probabilidade teórica de atingir um locus safe harbor por acaso" dos 4 sistemas. piggyBac e retrovírus MLV mostraram padrões inesperadamente semelhantes entre si, enriquecidos perto de locais de início de transcrição, colocalizando com sítios associados a BRD4 -- mecanismo de "tethering" convergente que os dirige preferencialmente para genes ativos (mais arriscado).';
update public_safe_harbors_staging set locus_name = 'Comparison of random-integration vectors (SB, piggyBac, MLV, lentivirus)', evidence_summary = 'Direct comparison of 4 systems in human CD4+ T cells: the Sleeping Beauty (SB) transposon showed the distribution closest to true randomness -- "highest theoretical probability of hitting a safe-harbor locus by chance" of the 4 systems. piggyBac and MLV retrovirus showed unexpectedly similar patterns to each other, enriched near transcription start sites, colocalizing with BRD4-associated sites -- a convergent "tethering" mechanism that preferentially directs them toward active genes (riskier).', stability = 'SB closest to true random distribution; piggyBac/MLV enriched near active genes (higher risk)' where source_pmid = '26755332' and evidence_summary = 'Comparação direta de 4 sistemas em células T CD4+ humanas: o transposão Sleeping Beauty (SB) mostrou a distribuição mais próxima do aleatório verdadeiro -- "maior probabilidade teórica de atingir um locus safe harbor por acaso" dos 4 sistemas. piggyBac e retrovírus MLV mostraram padrões inesperadamente semelhantes entre si, enriquecidos perto de locais de início de transcrição, colocalizando com sítios associados a BRD4 -- mecanismo de "tethering" convergente que os dirige preferencialmente para genes ativos (mais arriscado).';

update known_safe_harbors set locus_name = 'Sleeping Beauty (SB100X) via hybrid lentivirus/transposon vector', evidence_summary = 'Hybrid HIV-1/SB100X vector: integration up to 160x above background in cell lines and in primary human fibroblasts/keratinocytes. Lentiviral integrations showed a strong bias toward actively transcribed genes; in contrast, SB100X-mediated integrations from the same vector were far more gene-random -- confirms the safer profile of SB100X vs. conventional lentiviral integration.', stability = 'More gene-random distribution than conventional lentiviral integration' where source_pmid = '21468003' and evidence_summary = 'Vetor híbrido HIV-1/SB100X: integração até 160x acima do fundo em linhas celulares e em fibroblastos/queratinócitos primários humanos. Integrações lentivirais mostraram forte viés para genes ativamente transcritos; em contraste, as integrações mediadas por SB100X a partir do mesmo vetor foram muito mais aleatórias em relação a genes -- confirma o perfil mais seguro do SB100X face a integração lentiviral convencional.';
update public_safe_harbors_staging set locus_name = 'Sleeping Beauty (SB100X) via hybrid lentivirus/transposon vector', evidence_summary = 'Hybrid HIV-1/SB100X vector: integration up to 160x above background in cell lines and in primary human fibroblasts/keratinocytes. Lentiviral integrations showed a strong bias toward actively transcribed genes; in contrast, SB100X-mediated integrations from the same vector were far more gene-random -- confirms the safer profile of SB100X vs. conventional lentiviral integration.', stability = 'More gene-random distribution than conventional lentiviral integration' where source_pmid = '21468003' and evidence_summary = 'Vetor híbrido HIV-1/SB100X: integração até 160x acima do fundo em linhas celulares e em fibroblastos/queratinócitos primários humanos. Integrações lentivirais mostraram forte viés para genes ativamente transcritos; em contraste, as integrações mediadas por SB100X a partir do mesmo vetor foram muito mais aleatórias em relação a genes -- confirma o perfil mais seguro do SB100X face a integração lentiviral convencional.';

update known_safe_harbors set locus_name = 'Random integration (gammaretrovirus) -- founding historical case', evidence_summary = 'THE FOUNDING CASE of the entire safe-harbor field: gene therapy trial for SCID-X1 (10 patients). A gammaretroviral vector integrated 35kb upstream of the LMO2 proto-oncogene, in antisense orientation, causing LMO2 overexpression in the leukemic clone. Leukemogenesis also required additional acquired mutations (NOTCH1 gain-of-function, CDKN2A deletion, TCR-beta/STIL-TAL1 translocation) -- it was not the insertion alone, but the insertion was the initial trigger. This is the historical incident that justifies the existence of this entire safe-harbor catalog.', stability = 'Historical case establishing why safe-harbor loci matter (random integration triggered leukemogenesis)' where source_pmid = '18688286' and evidence_summary = 'O CASO FUNDADOR de todo o campo dos safe harbors: ensaio de terapia génica para SCID-X1 (10 doentes). Vetor gamaretroviral integrou 35kb a montante do protooncogene LMO2, em orientação antisense, causando sobre-expressão de LMO2 no clone leucémico. Leucemogénese precisou também de mutações adicionais adquiridas (NOTCH1 gain-of-function, deleção de CDKN2A, translocação TCR-beta/STIL-TAL1) -- não foi só a inserção, mas a inserção foi o gatilho inicial. É o incidente histórico que justifica a existência de todo este catálogo de safe harbors.';
